// ---- toggle column name -> data-column index (from the toggle-vis pills) ----
const COLS = {
  'No': 0,
  'Order Date': 1,
  'CSR': 2,
  'Verifier Name': 3,
  'Upsell By': 4,
  'Customer Name': 5,
  'Address': 6,
  'Province': 7,
  'City': 8,
  'Brgy': 9,
  'Zip': 10,
  'Contact': 11,
  'Order': 12,
  'Total Qty': 13,
  'Price (Final)': 14,
  'Page': 15,
  'Platform': 16,
  'Tracking No.': 17,
  'Courier': 18,
  'Parcel Status': 19,
  'Encoded Date': 20,
  'Parcel Update': 21,
  'Shipping Fee': 22,
  'MoP': 23,
  'Reserve': 24,
  'Reserve Date': 25,
  'Order Status': 26,
  'Shipped Out Date': 27,
  'Shift': 28,
  'Date Added': 29,
  'Price (Initial)': 30,
  'Price (Upsell)': 31,
  'Intern & Brands Name': 32,
  'Call Status': 33,
};

// >>> Which TOGGLE columns to keep (by name). Columns WITHOUT a toggle pill are
// always included automatically, so you don't list them here.
// (Default = the teal/active pills; white pills omitted: Zip, Reserve, Reserve Date, Shift, Call Status)
const WANT = Array.isArray(columns) && columns.length ? columns : [
  'Order Date',
  'CSR',
  'Verifier Name',
  'Upsell By',
  'Customer Name',
  'Address',
  'Province',
  'City',
  'Brgy',
