  'Page',
  'Platform',
  'Tracking No.',
  'Courier',
  'Parcel Status',
  'Encoded Date',
  'Parcel Update',
  'Shipping Fee',
  'MoP',
  'Order Status',
  'Shipped Out Date',
  'Date Added',
  'Price (Initial)',
  'Price (Upsell)',
  'Intern & Brands Name',
];

const wantIdx = WANT.map(n => COLS[n]).filter(i => i !== undefined);

if (cookies && cookies.length) {
  await $page.setCookie(...cookies);
}
await $page.setViewport({ width: 1512, height: 982, deviceScaleFactor: 1 });

async function snap(name) {
  try {
    const data = await $page.screenshot({ encoding: 'base64', fullPage: true });
    return { [name]: { data, mimeType: 'image/png', fileName: `${name}.png`, fileExtension: 'png' } };
  } catch (_) { return {}; }
}

// set a filter field robustly — works for <select> and date <input> (fires the events the page listens for)
async function setField(selector, value) {
  await $page.waitForSelector(selector, { timeout: 30000 });
  const tag = await $page.evaluate((sel) => {
    const el = document.querySelector(sel);
    return el ? el.tagName.toLowerCase() : null;
  }, selector);

  if (tag === 'select') {
    await $page.select(selector, value);
  } else {
    await $page.evaluate((sel, val) => {
      const el = document.querySelector(sel);
      if (!el) return;
      const proto = Object.getPrototypeOf(el);
      const setter = Object.getOwnPropertyDescriptor(proto, 'value')?.set;
      setter ? setter.call(el, val) : (el.value = val);
      el.dispatchEvent(new Event('input',  { bubbles: true }));
      el.dispatchEvent(new Event('change', { bubbles: true }));
      el.dispatchEvent(new KeyboardEvent('keyup', { bubbles: true }));
      if (el.blur) el.blur();
    }, selector, value);
  }
}

// Column rule:
//  - column HAS a toggle pill  -> keep only if its index is in wantIdx (selected by name)
//  - column has NO toggle pill -> always keep (the "extra" columns, e.g. Total COG)
//  - the Actions / id column (/view/ link) is always kept
async function selectColumns(wantIdxArr) {
  await $page.evaluate((idxArr) => {
    const norm = (s) => (s || '').replace(/\s+/g, ' ').trim().toLowerCase();
    const wantSet = new Set(idxArr);

    // indices that actually have a toggle pill on the page
    const toggleSet = new Set(
      Array.from(document.querySelectorAll('a.toggle-vis[data-column]'))
        .map(a => parseInt(a.getAttribute('data-column'), 10))
        .filter(n => !Number.isNaN(n))
    );

    const jq = window.jQuery || window.$;
    if (!(jq && jq.fn.dataTable && jq.fn.dataTable.isDataTable('#tblorders'))) return;

    const dt = jq('#tblorders').DataTable();
    dt.columns().every(function () {
      const idx = this.index();
      const th = this.header();
      const text = norm(th ? th.innerText : '');

      let hasViewLink = false;
      try {
        const nodes = this.nodes();
        for (let i = 0; i < nodes.length; i++) {
          if (nodes[i].querySelector && nodes[i].querySelector('a[href*="/view/"]')) { hasViewLink = true; break; }
        }
      } catch (_) {}

      // toggle column -> selected only; non-toggle column -> always include
      let keep = toggleSet.has(idx) ? wantSet.has(idx) : true;

      // never drop the actions/id column
      if (hasViewLink || text === 'actions') keep = true;

      this.visible(keep, false);
    });
    dt.columns.adjust().draw(false);
  }, wantIdxArr);

  await new Promise(r => setTimeout(r, 800)); // let the redraw settle
}

async function extractTable() {
  return await $page.evaluate(() => {
    const table = document.querySelector('table.dataTable') || document.querySelector('table');
    if (!table) return [];
    const headers = Array.from(table.querySelectorAll('thead th')).map(th => {
      const clone = th.cloneNode(true);
      clone.querySelectorAll('select, input, textarea, button').forEach(n => n.remove());
      return clone.innerText.trim();
    });
    return Array.from(table.querySelectorAll('tbody tr')).map(tr => {
      const cells = Array.from(tr.querySelectorAll('td'));
      if (!cells.length) return null;
      const obj = {};
      cells.forEach((td, i) => { obj[headers[i] || `col_${i}`] = td.innerText.trim(); });

      // pull the id out of the View action link (e.g. customer/view/916142 -> 916142)
      const viewLink = tr.querySelector('a[href*="/view/"]');
      if (viewLink) {
        const m = viewLink.getAttribute('href').match(/\/view\/(\d+)/);
        if (m) obj.id = m[1];
      }
      return obj;
    }).filter(Boolean);
  });
}

function normalize(row) {
  const out = {};
  for (const [rawKey, value] of Object.entries(row)) {
    const key = (rawKey || '').trim();
    if (!key) continue;
    if (/^col_\d+$/i.test(key)) continue;
    if (/[\n\r]/.test(key)) continue;
    if (/^(actions?|search)$/i.test(key)) continue;
    out[key] = value;
  }
  return out;
}

async function isNextDisabled() {
  return await $page.evaluate(() => {
    const nextLi = document.querySelector('li.next');
    return !nextLi || nextLi.classList.contains('disabled');
  });
}

